function restOn(road){ return REST.filter(function(r){ return r.road===road; }).sort(function(a,b){ return a.km-b.km; }); }
function restNear(road, pos){
  var south=null, north=null;
  restOn(road).forEach(function(r){
    if (r.km >= pos){ if (r.only==='dec') return; if (!south) south = r; }
    else { if (r.only==='inc') return; north = r; }
  });
  return {south:south, north:north};
}

