function wcOn(road){ return WC.filter(function(w){ return w.r === road; }).sort(function(a,b){ return a.k - b.k; }); }
function wcNear(road, pos){
  var south = null, north = null;
  wcOn(road).forEach(function(w){
    if (!w.s.length) return;
    if (w.k >= pos){ if (w.x === 'dec') return; if (!south) south = w; }
    else { if (w.x === 'inc') return; north = w; }
  });
  return {south:south, north:north};
}
/* exits a driver can still take: at least 1 km ahead in the travel direction */
function nextExits(road, km, dir, n){
  var all = wcOn(road), ahead = [], behind = [];
  all.forEach(function(w){
    if (w.k >= km + 1 && w.x !== 'dec') ahead.push(w);
    if (w.k <= km - 1 && w.x !== 'inc') behind.unshift(w);
  });
  if (dir === 'inc') return ahead.slice(0, n);
  if (dir === 'dec') return behind.slice(0, n);
  return ahead.slice(0, n).concat(behind.slice(0, n));
}
function metres(m){ return m >= 1000 ? (m/1000).toFixed(1) + ' 公里' : m + ' 公尺'; }

function endOf(j, road){ return j.ends[0].road===road ? j.ends[0] : (j.ends[1].road===road ? j.ends[1] : null); }
function between(r1, r2){ return J.filter(function(j){ return endOf(j,r1) && endOf(j,r2); }); }
function opp(d){ return d==='inc' ? 'dec' : 'inc'; }

/* cost of riding road C from junction jin to junction jout; Infinity if the ramps do not allow it */
function chainCost(C, jin, jout){
  var a = endOf(jin,C), b = endOf(jout,C);
  var d = Math.abs(a.km - b.km);
  var dir = b.km > a.km ? 'inc' : (b.km < a.km ? 'dec' : null);
  if (a.exit && dir && dir !== opp(a.exit)) return Infinity;
  if (b.exit && dir && dir !== b.exit) return Infinity;
  if (ROADS[C].t === 'main' && d > 30) return Infinity;
  if (jout.via) d += 20;
  return d;
}

function findRoutes(F, T){
  var out = [], names = Object.keys(ROADS);
  between(F,T).forEach(function(j){ out.push({roads:[F,T], js:[j]}); });
  names.forEach(function(C){
    if (C===F || C===T) return;
    var J1 = between(F,C), J2 = between(C,T);
    if (!J1.length || !J2.length) return;
    J1.forEach(function(j1){
      var best=null, bc=Infinity;
      J2.forEach(function(j2){ var c = chainCost(C,j1,j2); if (c < bc){ bc=c; best=j2; } });
      if (best) out.push({roads:[F,C,T], js:[j1,best]});
    });
  });
  if (!out.length){
    names.forEach(function(C1){
      if (C1===F || C1===T) return;
      names.forEach(function(C2){
        if (C2===F || C2===T || C2===C1) return;
        var J1 = between(F,C1), J2 = between(C1,C2), J3 = between(C2,T);
        if (!J1.length || !J2.length || !J3.length) return;
        J1.forEach(function(j1){
          var b2=null, c2=Infinity;
          J2.forEach(function(j2){ var c=chainCost(C1,j1,j2); if (c<c2){ c2=c; b2=j2; } });
          if (!b2) return;
          var b3=null, c3=Infinity;
          J3.forEach(function(j3){ var c=chainCost(C2,b2,j3); if (c<c3){ c3=c; b3=j3; } });
          if (b3) out.push({roads:[F,C1,C2,T], js:[j1,b2,b3], cost:c2+c3});
        });
      });
    });
    /* keep the shortest chain per first junction */
    var keep = {};
    out.forEach(function(r){ var id = J.indexOf(r.js[0]); if (!keep[id] || r.cost < keep[id].cost) keep[id]=r; });
    out = Object.keys(keep).map(function(k){ return keep[k]; });
  }
  out.forEach(function(r){ var e = endOf(r.js[0], F); r.km = e.km; r.exit = e.exit; r.show = e.show; });
  out.sort(function(a,b){ return a.km - b.km; });
  return out;
}

function kmText(e){ return e.show==='ok' ? e.km + 'K' : (e.show==='approx' ? '約 ' + e.km + 'K' : ''); }
function dirWord(road, d){ return ROADS[road].dirs[d==='inc' ? 1 : 0]; }

/* plain-language steps for one route */
function describe(r){
  var F = r.roads[0], T = r.roads[r.roads.length-1], steps = [], notes = [];
  var e0 = endOf(r.js[0], F);
  var first = F + ' ' + (kmText(e0) ? kmText(e0) + ' ' : '') + '「' + e0.name + '」下';
  steps.push(first);
  if (e0.exit) notes.push('這個交流道只有' + dirWord(F, e0.exit) + '有出口');
  for (var i=1; i<r.roads.length-1; i++){
    var C = r.roads[i], a = endOf(r.js[i-1], C), b = endOf(r.js[i], C);
    var d = b.km > a.km ? 'inc' : 'dec';
    var s = ('走 ' + C + ' ' + dirWord(C, d)).trim();
    var sg = r.js[i-1].signs;
    if (sg && r.js[i-1].ends[1].road === C && sg[d]) s += '，牌子找「' + sg[d] + '」';
    s += '，到「' + b.name + '」';
    steps.push(s);
  }
  var last = r.js[r.js.length-1], eT = endOf(last, T);
  var fin = '接 ' + T;
  if (r.roads.length > 2 || eT.name !== e0.name) fin += '（' + eT.name + (kmText(eT) ? ' ' + kmText(eT) : '') + '）';
  steps.push(fin);
  if (r.roads.length === 2 && last.signs && last.ends[1].road === T){
    notes.push('牌子：' + dirWord(T,'dec') + '「' + last.signs.dec + '」、' + dirWord(T,'inc') + '「' + last.signs.inc + '」');
  }
  r.js.forEach(function(j){ if (j.via) notes.push(j.via); });
  if (eT.exit) notes.push('這裡只能上 ' + T + ' ' + dirWord(T, opp(eT.exit)));
  return {steps:steps, notes:notes};
}

/* one-line version for the list */
function oneLine(r){
  var T = r.roads[r.roads.length-1], parts = [];
  for (var i=1; i<r.roads.length-1; i++){
    var C = r.roads[i], a = endOf(r.js[i-1], C), b = endOf(r.js[i], C);
    parts.push((C + ' ' + dirWord(C, b.km > a.km ? 'inc' : 'dec')).trim());
  }
  var eT = endOf(r.js[r.js.length-1], T);
  parts.push((r.roads.length > 2 ? '在「' + eT.name + '」' : '') + '接 ' + T + (r.roads.length > 2 && kmText(eT) ? ' ' + kmText(eT) : ''));
  return parts.join(' → ');
}

/* nearest usable route each way from position pos on the first road */
function nearest(routes, pos){
  var south=null, north=null;
  routes.forEach(function(r){
    if (r.km >= pos){ if (r.exit && r.exit!=='inc') return; if (!south || r.km < south.km) south = r; }
    else { if (r.exit && r.exit!=='dec') return; if (!north || r.km > north.km) north = r; }
  });
  return {south:south, north:north};
}

/* ---------- reading a spoken sentence ---------- */
var CN = {'零':0,'〇':0,'一':1,'二':2,'兩':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9};
function cnToNum(s){
  if (!/[十百]/.test(s)){ var o=''; for (var i=0;i<s.length;i++) o += CN[s[i]]; return parseInt(o,10); }
  var total=0, cur=0, lastUnit=1;
  for (var k=0;k<s.length;k++){
    var ch=s[k];
    if (ch==='百'){ total += (cur||1)*100; cur=0; lastUnit=100; }
    else if (ch==='十'){ total += (cur||1)*10; cur=0; lastUnit=10; }
    else { cur = CN[ch]; }
  }
  if (cur){ total += (lastUnit===100 && s[s.length-2]!=='零' && s[s.length-2]!=='〇' && !/十/.test(s)) ? cur*10 : cur; }
  return total;
}
var ROADNUM = {61:1,62:1,63:1,64:1,65:1,66:1,68:1,72:1,74:1,76:1,78:1,82:1,84:1,86:1,88:1};
var NATNUM = {1:1,2:1,3:1,4:1,5:1,6:1,8:1,10:1};

function parseQuery(raw){
  var res = {from:null, to:null, km:null, city:null, dir:null};
  if (!raw) return res;
  var s = raw.replace(/[０-９]/g, function(c){ return String.fromCharCode(c.charCodeAt(0)-65248); })
             .replace(/臺/g,'台').replace(/\s+/g,' ');
  var wantWC = /廁所|洗手間|超商|便利商店|小七|全家|7-?11|seven/i.test(s);
  s = s.replace(/上?廁所|洗手間|超商|便利商店|小七|全家|7-?11|seven/ig, ' ');
  var wantGas = /加油|中油|台塑|台亞|全國加油/.test(s);
  s = s.replace(/加油站?|中油|台塑|台亞|全國加油站?/g, ' ');
  var wantRest = /休息|服務區/.test(s);
  s = s.replace(/休息站?|服務區/g, ' ');
  if (/南下|往南|向南/.test(s)) res.dir = 'inc'; else if (/北上|往北|向北/.test(s)) res.dir = 'dec';
  s = s.replace(/南下|往南|向南|北上|往北|向北/g, ' ');
  /* places first, so 三重 / 五股 / 八里 are not read as numbers */
  var names = Object.keys(CITY).sort(function(a,b){ return b.length-a.length; });
  var firstAt = Infinity;
  for (var i=0;i<names.length;i++){
    var p = s.indexOf(names[i]);
    while (p >= 0){
      if (names[i]==='台西' && /^台西濱/.test(s.slice(p))) { p = s.indexOf(names[i], p+1); continue; }
      if (p < firstAt){ firstAt = p; res.city = names[i]; }
      s = s.slice(0,p) + '§§'.slice(0, names[i].length) + s.slice(p+names[i].length);
      p = s.indexOf(names[i], p+1);
    }
  }
  s = s.replace(/中山高(速公路)?/g,'國1').replace(/北二高|福爾摩沙高速公路|福高/g,'國3').replace(/西濱(快速)?(公路|道路)?/g,'台61');
  s = s.replace(/[零〇一二兩三四五六七八九十百]+/g, function(m){ var n = cnToNum(m); return isNaN(n) ? m : String(n); });
  s = s.replace(/(^|[^0-9])1高/g,'$1國1').replace(/(^|[^0-9])[23]高/g,'$1國3');
  /* distance markers */
  s = s.replace(/(\d{1,3}(?:\.\d)?)\s*(公里|km|KM|Km|k|K)(?![a-zA-Z])/g, function(m,n){ if (res.km===null) res.km = parseFloat(n); return ' '; });
  var hits = [];
  s = s.replace(/國道?\s*(\d{1,2})\s*號?/g, function(m,n,off){ n=parseInt(n,10); if (NATNUM[n]){ hits.push({road:'國'+n, at:off}); return m.replace(/\d/g,'#'); } return m; });
  s.replace(/(?:台|省道|快速道路|快速公路|快速)?\s*(\d{1,3})(?:\s*(?:號|線))?/g, function(m,n,off){
    n = parseInt(n,10);
    if (ROADNUM[n]) hits.push({road:'台'+n, at:off});
    else if (res.km===null && n<=430 && !/^(?:台|省道|快速)/.test(m)) res.km = n;
    return m;
  });
  hits.sort(function(a,b){ return a.at-b.at; });
  hits.forEach(function(h){
    var before = s.slice(Math.max(0,h.at-5), h.at);
    h.role = /(接|到|轉|上|去|往|找)[^在從走]{0,3}$/.test(before) ? 'to' : (/(在|從|走|開)[^接到轉上去往找]{0,3}$/.test(before) ? 'from' : null);
  });
  var to = hits.filter(function(h){ return h.role==='to'; })[0];
  var from = hits.filter(function(h){ return h.role==='from'; })[0];
  var rest = hits.filter(function(h){ return h!==to && h!==from; });
  if (!from && !to){
    if (rest.length >= 2){ from = rest[0]; to = rest[1]; }
    else if (rest.length === 1){ to = rest[0]; }
  } else if (!to && rest.length){ to = rest.filter(function(h){ return h.road!==from.road; })[0] || null; }
  else if (!from && rest.length){ from = rest.filter(function(h){ return h.road!==to.road; })[0] || null; }
  if (wantWC || wantRest || wantGas){ from = from || to || rest[0] || null; res.from = from ? from.road : null; res.to = wantGas ? 'GAS' : (wantWC ? 'WC' : 'REST'); return res; }
  res.from = from ? from.road : null; res.to = to ? to.road : null;
  return res;
}

